const tabId = 787783793;

const cards = await browserjs(tabId, () => {
  const result = [];
  // Find all cards or containers with headings
  const headings = document.querySelectorAll("h3");
  for (const h of headings) {
    const title = h.textContent.trim();
    // find container
    const container = h.closest("div");
    // find nearest anchor
    let a = h.closest("a") || container?.querySelector("a") || h.parentElement?.querySelector("a");
    // Or traverse upwards
    let curr = h;
    while (curr && !a && curr !== document.body) {
      curr = curr.parentElement;
      if (curr) a = curr.querySelector("a[href]");
    }
    const text = container ? container.innerText.trim() : "";
    result.push({
      title,
      href: a ? a.href : null,
      snippet: text.slice(0, 300)
    });
  }
  return result;
});

console.log("Extracted cards:", cards.length);
cards.slice(0, 25).forEach((c, i) => console.log(`${i+1}. [${c.title}] -> ${c.href}`));

