const tabId = 787783793;

const nsfOpps = await browserjs(tabId, () => {
  const rows = [];
  const items = document.querySelectorAll(".funding-search-result, tbody tr, .views-row");
  // Let's also extract links to opportunities
  const links = Array.from(document.querySelectorAll("a[href*='/funding/opportunities/']")).map(a => {
    const parent = a.closest(".views-row") || a.closest("tr") || a.parentElement.parentElement;
    return {
      title: a.textContent.trim(),
      href: a.href,
      details: parent ? parent.innerText.trim().replace(/\s+/g, " ") : ""
    };
  });
  return links;
});

