const tabId = 787783793;

// Let's test clipboard paste into OnlyOffice
const testText = "TEST CLIPBOARD PASTE";
const testHtml = "<p><strong>TEST CLIPBOARD PASTE</strong></p>";

try {
  await browserjs(tabId, async (text, html) => {
    await navigator.clipboard.write([new ClipboardItem({
      "text/plain": new Blob([text], { type: "text/plain" }),
      "text/html": new Blob([html], { type: "text/html" })
    })]);
  }, testText, testHtml);
  console.log("Wrote to clipboard");

  await tool.press({ tabId, keys: "ControlOrMeta+v" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

  const shot = await browser.screenshot({ tabId });
  console.log("Screenshot after paste:", shot.image);
} catch (e) {
  console.log("Clipboard test error:", e.message);
}

